// Mechanical packaging of the tested engine for opaque-origin iframe previews.
import {readFileSync, writeFileSync} from 'node:fs';
const base = new URL('../web/', import.meta.url);
const model = readFileSync(new URL('model.js',base),'utf8').replace(/^export /gm,'');
const worker = readFileSync(new URL('worker.js',base),'utf8').replace(/^import .*;\n/,'');
writeFileSync(new URL('worker-source.js',base),
  '// Generated by npm run build; do not edit. Source: model.js + worker.js.\nexport const WORKER_SOURCE = '+
  JSON.stringify(model+'\n'+worker)+';\n');
